import{_ as r,o as n,c as a,ae as t}from"./chunks/framework.Cqu5Y2mC.js";const g=JSON.parse('{"title":"IT-Projekt CitBin – Protokoll, 13.März","description":"","frontmatter":{},"headers":[],"relativePath":"05-Gemeinsam/2026-03-13-Protokoll.md","filePath":"05-Gemeinsam/2026-03-13-Protokoll.md"}'),i={name:"05-Gemeinsam/2026-03-13-Protokoll.md"};function l(s,e,o,d,h,u){return n(),a("div",null,[...e[0]||(e[0]=[t(`<h1 id="it-projekt-citbin-–-protokoll-13-marz" tabindex="-1">IT-Projekt CitBin – Protokoll, 13.März <a class="header-anchor" href="#it-projekt-citbin-–-protokoll-13-marz" aria-label="Permalink to &quot;IT-Projekt CitBin – Protokoll, 13.März&quot;">​</a></h1><h2 id="teilnehmer" tabindex="-1">Teilnehmer: <a class="header-anchor" href="#teilnehmer" aria-label="Permalink to &quot;Teilnehmer:&quot;">​</a></h2><p><strong>Von der Stadt:</strong></p><ul><li>Fr.Bieler</li></ul><p><strong>Lehrer:</strong></p><ul><li>Hr.Laber</li></ul><p><strong>Sybit:</strong></p><ul><li>Hr. Strittmatter</li></ul><p><strong>Schüler:</strong></p><ul><li>Eray, Lukas, Irakli, Huzaifa, Marius</li><li>Theodor, Felix, Jannick, Marlon</li><li>Sofia, Daniel</li></ul><h2 id="protokollanten" tabindex="-1">Protokollanten: <a class="header-anchor" href="#protokollanten" aria-label="Permalink to &quot;Protokollanten:&quot;">​</a></h2><p>Sofia.Jäger, Daniel.Saracoglu</p><h2 id="_1-ruckblick-ergebnisse-2025" tabindex="-1">1. Rückblick Ergebnisse 2025 <a class="header-anchor" href="#_1-ruckblick-ergebnisse-2025" aria-label="Permalink to &quot;1. Rückblick Ergebnisse 2025&quot;">​</a></h2><ul><li><p>Testphase: Ausprobiert, welche Technologie am besten funktioniert</p></li><li><p>Technologie 1: <strong>Ultraschallsensor</strong> hat nicht funktioniert, da am Rand des Mülleimers reflektiert wird —&gt; <strong>falsches Ergebnis</strong></p></li></ul><p>Technologie 2: <strong>Laser</strong><br> Funktioniert besser.<br><strong>Nachteile: Geht durch Plastik durch, Spinnennetz setzt Funktion außer Kraft</strong></p><p>Technologie 3: <strong>Apollon-Q Radar</strong><br> Laser und Radar<br> soll am besten funktionieren<br> Abmaße bekannt<br><strong>150€ pro Stück</strong><br> Wir bekommen ein oder zwei Sensoren: Zeitpunkt noch unbekannt<br><strong>Batterie/ Lebensdauer: 5-7 Jahre</strong></p><p>Prototyp Mülleimer im Rathaus installiert —&gt; Jetzt in HGS<br><strong>Website programmiert:</strong> Mülleimerverwaltung (hinzufügen, löschen, bearbeiten, Status, Update, Standort, etc. der Mülleimer)</p><h2 id="lora-wan-als-netzwerk" tabindex="-1">LoRa-WAN als Netzwerk: <a class="header-anchor" href="#lora-wan-als-netzwerk" aria-label="Permalink to &quot;LoRa-WAN als Netzwerk:&quot;">​</a></h2><p>Wird akutell noch verwendet Bricht zusammen, bei zu vielen Mülleimern soll ersetzt werden durch Mioty</p><h3 id="mioty-als-netzwerk-weniger-storeinflusse-lauft-stabiler" tabindex="-1">Mioty als Netzwerk: Weniger Störeinflüsse &amp; läuft stabiler. <a class="header-anchor" href="#mioty-als-netzwerk-weniger-storeinflusse-lauft-stabiler" aria-label="Permalink to &quot;Mioty als Netzwerk: Weniger Störeinflüsse &amp; läuft stabiler.&quot;">​</a></h3><ul><li>Empfänger der Daten: Indoor Gateway<br><em>Muss drinnen sein</em><br> Ersetzt Antenne, zwei Stück von der Firma bekommen.<br> Einen für die HGS und einen für das Rathaus.</li></ul><h3 id="ruckmeldung-von-stadt-singen" tabindex="-1">Rückmeldung von Stadt Singen: <a class="header-anchor" href="#ruckmeldung-von-stadt-singen" aria-label="Permalink to &quot;Rückmeldung von Stadt Singen:&quot;">​</a></h3><pre><code>So schnell und weit ausweiten/ ausbauen, soweit es geht (bis irgendwann alle Mülleimer abgedeckt sind).
Budget: 30 Sensoren in Innenstadt
Fläche: Innenstadt bis zum Bahnhof, bis zum Stadtgarten, bis zum Hallenbad/ Esso-Tankstelle
Ampelsystem ist gut für Mitarbeiter.  
Ampelsystem soll beibehalten werden wie es ist.
</code></pre><h3 id="ampelsystem" tabindex="-1">Ampelsystem: <a class="header-anchor" href="#ampelsystem" aria-label="Permalink to &quot;Ampelsystem:&quot;">​</a></h3><pre><code>Drei bekannte Zustände für Füllstand:  
Rot(Voll)  
Gelb(Könnte geelert werden)  
Grün(Leer)  
</code></pre><h3 id="fragen-an-die-stadt-singen" tabindex="-1">Fragen an die Stadt Singen: <a class="header-anchor" href="#fragen-an-die-stadt-singen" aria-label="Permalink to &quot;Fragen an die Stadt Singen:&quot;">​</a></h3><pre><code>Wie oft soll gesendet werden (Messzyklen)
Mehrere Sendung = Höhere Akkuverbrauch
Um wie viel Uhr soll gemeldet werden
Vermutung von Stephan Strittmatter: 2 Messungen pro Tag sollten reichen.
Ausnahmen bei Events 
Statistik/ Rückmeldung: Müssen alle Mülleimer gleich oft  Daten senden  
</code></pre><h3 id="frage-an-hardware" tabindex="-1">Frage an Hardware: <a class="header-anchor" href="#frage-an-hardware" aria-label="Permalink to &quot;Frage an Hardware:&quot;">​</a></h3><p><strong>Kann man im Nachhinein nach Installation nochmal Messzyklen einstellen?</strong></p><h2 id="losung-fur-pfandflschensammler" tabindex="-1">Lösung für Pfandflschensammler: <a class="header-anchor" href="#losung-fur-pfandflschensammler" aria-label="Permalink to &quot;Lösung für Pfandflschensammler:&quot;">​</a></h2><ul><li><p>Problem:<br> Sammler öffnen die Mülleimer um Flaschen zu finden, sie könnten den Sensor finden und ihn klauen.</p></li><li><p>Lösung:<br> Außen eine Halterung anbringen in den passanten die Flaschen abstellen(Mülleimer bleiben so geschlossen).</p></li></ul><h1 id="_2-ziele-bis-ende-des-schuljahres" tabindex="-1">2 .Ziele bis Ende des Schuljahres: <a class="header-anchor" href="#_2-ziele-bis-ende-des-schuljahres" aria-label="Permalink to &quot;2 .Ziele bis Ende des Schuljahres:&quot;">​</a></h1><pre><code>Frage der Installation/ Hardware:
Wo soll der Sensor genau im Mülleimer installiert werden
Zuerst: Tests zur Verbindung
Frage an die Stadt: Weitere Testmülleimer
Welche 2-3 Mülleimer sollen noch als Testmülleimer hinzugefügt werden.  
</code></pre><h2 id="mit-hardware-infrastruktur-testen-und-sprechen" tabindex="-1">Mit Hardware/Infrastruktur testen und sprechen: <a class="header-anchor" href="#mit-hardware-infrastruktur-testen-und-sprechen" aria-label="Permalink to &quot;Mit Hardware/Infrastruktur testen und sprechen:&quot;">​</a></h2><pre><code>Wir bekommen eine aktuelle Liste mit den Standorten der Mülleimer (eventuell mit Koordinaten)
Frage an Hardware/ Infrastruktur: Standort Empfangsstation
Testen, wo man Signale empfängt
Standort einer weiteren potentiellen Empfangsstation ermitteln.
</code></pre><h2 id="aufgaben-erwartung-und-ziele-fur-teams-besprochen" tabindex="-1">Aufgaben/ Erwartung und Ziele für Teams besprochen: <a class="header-anchor" href="#aufgaben-erwartung-und-ziele-fur-teams-besprochen" aria-label="Permalink to &quot;Aufgaben/ Erwartung und Ziele für Teams besprochen:&quot;">​</a></h2><pre><code>Siehe GitHub.
Idee von Stephan Strittmatter:
Wie bei Glascontainern: veröffentlichen, wo die Mülleimer sind
QR-Code auf den Mülleimer,
Weiterleitung zu veröffentlichten Deutschlandkarte
QR-Code ist zeitgemäßer als Flyer
QR-Code Aufkleber.  
</code></pre><h1 id="_3-ruckblick-ausblick-besuch-bei-firma-ifm" tabindex="-1">3. Rückblick/ Ausblick: Besuch bei Firma ifm: <a class="header-anchor" href="#_3-ruckblick-ausblick-besuch-bei-firma-ifm" aria-label="Permalink to &quot;3. Rückblick/ Ausblick: Besuch bei Firma ifm:&quot;">​</a></h1><ul><li>Besuch vor 3 Wochen</li><li>Problematik der Sensorplatzierung im Mülleimer diskutiert</li><li>Es gibt eine OpenSource Software (auch in GitHub anwendbar)</li></ul><h1 id="_4-organisation" tabindex="-1">4. Organisation: <a class="header-anchor" href="#_4-organisation" aria-label="Permalink to &quot;4. Organisation:&quot;">​</a></h1><ul><li><strong>Kontaktpersonen:</strong><br> Hauptansprechpartnerin: Samira Bieler<br> Sie leitet Informationen an Kontakte intern weiter.<br> E-Mail-Adresse: <a href="mailto:samira.bieler@singen.de" target="_blank" rel="noreferrer">samira.bieler@singen.de</a><br> Telefonnummer: 07731/ 85-177</li></ul><h3 id="anliegen-an-projektleitung" tabindex="-1">Anliegen an Projektleitung: <a class="header-anchor" href="#anliegen-an-projektleitung" aria-label="Permalink to &quot;Anliegen an Projektleitung:&quot;">​</a></h3><pre><code>Termine frühzeitig vereinbaren (2-3 Wochen früher)
Termine frühzeitig absagen/ Probleme kommunizieren
Mehrere Termine zur Auswahl senden
Danach  nochmal Outlook Einladung senden  
</code></pre><h2 id="github" tabindex="-1">GitHub: <a class="header-anchor" href="#github" aria-label="Permalink to &quot;GitHub:&quot;">​</a></h2><ul><li>GitHub ist der Haupt-Ablageort.</li><li>Nach Priorität gerankt</li><li>Alle müssen auf alle Informationen Zugriff haben (Ergebnisse, Daten) auch im Krankheitsfall.</li><li>Jedes Team hat seinen eigenen Ordner</li><li>Allgemeine Veröffentlichungen in einem Ordner für alle.</li></ul><h2 id="notengebung" tabindex="-1">Notengebung: <a class="header-anchor" href="#notengebung" aria-label="Permalink to &quot;Notengebung:&quot;">​</a></h2><ul><li><p>Zweimal Rückmeldung/ Feedback Gespräch, Erreichung der Ergebnisse reflektieren.</p></li><li><p>Es gibt eine Teamnote.</p></li><li><p>Innerhalb der Gruppe hat man gewissen Spielraum von ca. 1-2Notenpunkten.</p></li><li><p>Teammitglieder bestimmen selbst, wer welche Note bekommt.</p></li><li><p>Insgesamt muss man auf den Teamdurchschnitt kommen .</p></li><li><p>Man weiß vorher die Note wahrscheinlich nicht und muss die Teammitglieder erst gegenseitig einschätzen.</p></li><li><p>Gruppeneinschätzung wird auch mit Stadt besprochen/ eingeschätzt.</p></li></ul><h1 id="_5-kontakdaten" tabindex="-1">5. Kontakdaten: <a class="header-anchor" href="#_5-kontakdaten" aria-label="Permalink to &quot;5. Kontakdaten:&quot;">​</a></h1><p>Stephan Strittmatter: <a href="mailto:stephan.strittmatter@sybit.de" target="_blank" rel="noreferrer">stephan.strittmatter@sybit.de</a><br> Andre Sommer: <a href="mailto:andre.sommer@sybit.de" target="_blank" rel="noreferrer">andre.sommer@sybit.de</a><br> Samira Bieler: <a href="mailto:samira.bieler@singen.de" target="_blank" rel="noreferrer">samira.bieler@singen.de</a><br> Karl Laber: karl.laber@hgs-singen.online<br> Stefan Martin: stefan.martin@hgs-singen.online<br> Oliver Bucher: <a href="mailto:oliver.bucher@ifm.com" target="_blank" rel="noreferrer">oliver.bucher@ifm.com</a><br> (ifm, Director I4.0 Systems and Applications Germany)<br> Dr. Alexander Kahlig: <a href="mailto:alexander.kahlig@ifm.com" target="_blank" rel="noreferrer">alexander.kahlig@ifm.com</a><br> (Sentinum UG, Geschäftsführer)<br> Sofia Jäger: so.jaeger@hgs-singen.online<br> Daniel Saracoglu: d.saracoglu@hgs-singen.online</p><h1 id="_6-sprecher-mitglieder-der-jeweiligen-gruppen" tabindex="-1">6. Sprecher &amp; Mitglieder der jeweiligen Gruppen: <a class="header-anchor" href="#_6-sprecher-mitglieder-der-jeweiligen-gruppen" aria-label="Permalink to &quot;6. Sprecher &amp; Mitglieder der jeweiligen Gruppen:&quot;">​</a></h1><p><strong>Software:</strong> Felix (GS), Jannick (stellv. GS), Theodor (TM)<br><strong>Hardware:</strong> Eray (GS), Lukas (stellv. GS), Marlon (TM)<br><strong>Betrieb:</strong> Marius (GS), Artem (stellv. GS), Huzaifa (TM), Irakli (TM)<br><strong>Projektleitung:</strong> Daniel (GS), Sofia (stellv. GS), Jan (TM)</p><p><em><strong>GS = Gruppensprecher, stellv.GS = stellvertretender Gruppensprecher, TM = Teammitglied.</strong></em></p>`,52)])])}const c=r(i,[["render",l]]);export{g as __pageData,c as default};
